    if (doc.cancelled || videoLocked(doc)) adminVideoFail(409, 'PROJECT_LOCKED');
    const ingress = (doc.ingresses ?? []).find(value => value.operationId === operationId);
    if (ingress && (ingress.kind !== kind || ingress.expectedRevision !== expectedRevision)) adminVideoFail(409, 'OPERATION_CONFLICT');
    if (expectedRevision !== doc.revision && !ingress) adminVideoFail(409, 'REVISION_CONFLICT');
    if (doc.assets.some(asset => asset.operationId === operationId)) adminVideoFail(409, 'OPERATION_CONFLICT');
