    if (file.path) for await (const part of createReadStream(file.path)) { bytes += part.length; hash.update(part); }
    else { if (!file.buffer) adminVideoFail(400, 'INVALID_FILE'); bytes = file.buffer.length; hash.update(file.buffer); }
    if (bytes !== file.size) adminVideoFail(400, 'INVALID_FILE'); return hash.digest('hex');
